
(()=>{
const root=document.getElementById('mech-loading-preview');
const artwork={"gorilla": "data:image/jpeg;base64,", "rhino": "data:image/jpeg;base64,", "hippo": "data:image/jpeg;base64,", "kangaroo": "data:image/jpeg;base64,", "pangolin": "data:image/jpeg;base64,", "bison": "data:image/jpeg;base64,", "cobra": "data:image/jpeg;base64,", "fennec": "data:image/jpeg;base64,"};
const squads={allied:[['gorilla','YOU',100],['rhino','IRONCLAD',100],['fennec','WAYFINDER',87],['kangaroo','UPPERCUT',100],['hippo','DEEPWATER',76]],enemy:[['bison','FURNACE',100],['cobra','AFTERIMAGE',91],['pangolin','POLARITY',100],['rhino','BEDROCK',83],['gorilla','WARDEN',100]]};
for(const [team,rows] of Object.entries(squads)){
const roster=root.querySelector('[data-team="'+team+'"]');
rows.forEach(([mech,pilot,pct],i)=>{const el=document.createElement('article');el.className='pilot'+(pilot==='YOU'?' you':'');el.style.setProperty('--pct',pct+'%');el.innerHTML='<div class="portrait"><img alt="'+mech+' mech card" src="'+artwork[mech]+'"><span class="serial">'+(pilot==='YOU'?'YOU':'0'+(i+1))+'</span><div class="identity"><small>'+pilot+'</small><b>'+mech.toUpperCase()+'</b></div></div><div class="pilot-footer"><div class="pilot-status"><span>'+ (pct===100?'Ready':'Connecting')+'</span><strong>'+pct+'%</strong></div><div class="track"><div class="fill"></div></div></div>';roster.appendChild(el);});
}
const state={progress:76};function render(){root.style.setProperty('--load',state.progress+'%');root.querySelector('#mech-loading-percent').textContent=state.progress+'%';root.querySelector('[role="progressbar"]').setAttribute('aria-valuenow',state.progress);root.querySelector('#mech-loading-status').textContent=state.progress===100?'SQUADS READY · DEPLOYING':'SYNCHRONIZING SQUADS';}
render();if(globalThis.Tweak){const tweak=new Tweak({container:root,onChange:render});tweak.addSlider(state,'progress',{label:'Loading progress',min:0,max:100,unit:'%'});}
})();
